with open('json/gasstations.json', 'r') as f:
    data = json.load(f)
# Check all ChainID to Country mappings
chain_countries = {}
for r in data['records']:
    chain_id = r['ChainID']
    country = r['Country']
    if chain_id not in chain_countries:
        chain_countries[chain_id] = set()
    chain_countries[chain_id].add(country)

# Check if any chain has multiple countries
multi_country_chains = {k: v for k, v in chain_countries.items() if len(v) > 1}
print('Chains with multiple countries:', multi_country_chains)
print('All chains have single country:', len(multi_country_chains) == 0)

# Show all countries per chain
for chain_id in sorted(chain_countries.keys()):
    print(f'ChainID {chain_id}: {chain_countries[chain_id]}')"}}
